"""`harness site` — generate a MkDocs site from a downstream Harness project."""

from __future__ import annotations

from pathlib import Path

from rich.console import Console


def cmd_site(
    *,
    root: Path,
    out: Path,
    serve: bool = False,
    port: int = 8000,
    no_build: bool = False,
    clean: bool = False,
    include_internal: bool = False,
    strict: bool = False,
    logo: Path | None = None,
    favicon: Path | None = None,
    kpi_window: int = 7,
) -> int:
    """Generate the site. Returns process exit code."""
    console = Console()
    err = Console(stderr=True)

    if not root.exists():
        err.print(f"[red]root not found: {root}[/red]")
        return 1

    # Import here so the dep cost is paid only when the command runs
    from harness.site.builder import build_site, serve_site

    # Validate optional asset paths before kicking off the build
    for label, p in (("logo", logo), ("favicon", favicon)):
        if p is not None and not p.exists():
            err.print(f"[red]{label} not found: {p}[/red]")
            return 1

    try:
        result = build_site(
            root=root,
            out=out,
            include_internal=include_internal,
            clean=clean,
            strict=strict,
            do_build=not no_build,
            logo=logo,
            favicon=favicon,
            kpi_window_days=kpi_window,
        )
    except Exception as exc:
        err.print(f"[red]site build failed: {exc}[/red]")
        return 1

    console.print(f"[green]wrote[/green] {result.files_written} source file(s) under {result.out_dir}")
    if result.mkdocs_built:
        console.print(f"[green]HTML built[/green] → open [bold]{result.site_dir / 'index.html'}[/bold]")
    elif no_build:
        console.print("[dim]skipped mkdocs build (--no-build); markdown source only[/dim]")
    else:
        console.print("[yellow]mkdocs build did not run; markdown source only[/yellow]")

    if serve:
        if no_build:
            err.print("[yellow]--serve ignored because --no-build was set[/yellow]")
            return 0
        console.print(f"[cyan]serving on[/cyan] http://127.0.0.1:{port} (Ctrl-C to stop)")
        try:
            serve_site(out=result.out_dir, port=port)
        except KeyboardInterrupt:
            console.print("[dim]server stopped[/dim]")
        except Exception as exc:
            err.print(f"[red]serve failed: {exc}[/red]")
            return 1
    return 0
